#!/usr/bin/env bash
# ==============================================================================
# HiveOS Custom Miner Configuration Generator
# ==============================================================================

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_FILE="${CUSTOM_CONFIG_FILENAME:-/hive/miners/custom/matrix-worker/worker.conf}"

mkdir -p "$(dirname "$CONFIG_FILE")"

cat <<EOF > "$CONFIG_FILE"
# Distributed Matrix Multiply Worker Configuration (Generated by HiveOS)
${CUSTOM_USER_CONFIG}
EOF

# Ensure payout address is populated from %WAL% if set
if [ -n "$CUSTOM_TEMPLATE" ] && ! grep -q "MATRIX_WORKER_PAYOUT_ADDRESS" "$CONFIG_FILE"; then
    echo "MATRIX_WORKER_PAYOUT_ADDRESS=${CUSTOM_TEMPLATE}" >> "$CONFIG_FILE"
fi

if [ -n "$CUSTOM_SERVER" ] && ! grep -q "MATRIX_WORKER_NOSTR_RELAYS" "$CONFIG_FILE"; then
    echo "MATRIX_WORKER_NOSTR_RELAYS=${CUSTOM_SERVER}" >> "$CONFIG_FILE"
fi

echo "[+] HiveOS worker configuration written to $CONFIG_FILE"
